#Requires -Version 7.0
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$CompilerPath
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

# Compiles debug/TeclaScore-Completo.iss (generated by tools/build_debug.py with the current version)
# into debug/saida, keeping only the installer of this version there.
$projectRoot = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$kitRoot = Join-Path $projectRoot 'debug'
$script = Join-Path $kitRoot 'TeclaScore-Completo.iss'
[xml]$project = [IO.File]::ReadAllText((Join-Path $projectRoot 'src/Teclas.App/Teclas.App.csproj'))
$version = [string]$project.Project.PropertyGroup.Version
if ($version -notmatch '^\d+\.\d+\.\d+$') { throw 'A versão do projeto deve ser X.Y.Z.' }
$manifestPath = Join-Path $kitRoot 'kit-manifest.json'
if (-not [IO.File]::Exists($manifestPath) -or -not [IO.File]::Exists($script)) { throw 'Prepare a distribuição antes: o kit debug ou seu script .iss não existe.' }
$manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
if ($manifest.version -cne $version) { throw "O kit debug está na versão $($manifest.version); prepare a distribuição da $version." }
if ((Get-Content -LiteralPath $script -Raw) -notmatch ('#define AppVersion "' + [regex]::Escape($version) + '"')) { throw 'O script .iss não corresponde à versão atual.' }
# Only the managed files are trusted as payload; a hand-edited kit file stops the build.
foreach ($entry in $manifest.files.PSObject.Properties) {
    $path = Join-Path $kitRoot $entry.Name
    if (-not [IO.File]::Exists($path) -or (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $entry.Value) {
        throw "Arquivo do kit ausente ou alterado: $($entry.Name)"
    }
}
$compiler = (Resolve-Path -LiteralPath $CompilerPath).Path
$versionText = (& $compiler '/?' 2>&1 | Out-String)
if ($versionText -notmatch 'Inno Setup 7') { throw 'Use o compilador oficial Inno Setup 7.' }

$output = Join-Path $kitRoot 'saida'
[IO.Directory]::CreateDirectory($output) | Out-Null
$filename = "TeclaScore-$version-Completo-Setup-x64.exe"
$log = & $compiler '/Q' $script 2>&1 | Out-String
if ($LASTEXITCODE -ne 0) { throw "O Inno Setup não compilou o instalador completo (código $LASTEXITCODE). $($log.Trim())" }
$installer = Join-Path $output $filename
if (-not [IO.File]::Exists($installer)) { throw 'O compilador não produziu o instalador completo esperado.' }
foreach ($old in Get-ChildItem -LiteralPath $output -Filter 'TeclaScore-*-Completo-Setup-x64.exe' -File) {
    if ($old.Name -cne $filename) { Remove-Item -LiteralPath $old.FullName -Force }
}
[pscustomobject]@{
    installer = $installer; version = $version
    sha256 = (Get-FileHash -LiteralPath $installer -Algorithm SHA256).Hash.ToLowerInvariant()
    bytes = (Get-Item -LiteralPath $installer).Length; script = $script
} | ConvertTo-Json
